import type { ListeningScenario, Detail } from './listening-model.js';
const row = (value: string): Detail => {
  const [label, answer, reason, options] = value.split('|');
  return [label!, answer!, reason!, options?.split(';')];
};
const site = (title: string, topic: string, centerLabel: string, orientation: 'map' | 'plan', band: number, context: string, details: string[], closing: string): ListeningScenario => ({ title, topic, centerLabel, orientation, band, context, details: details.map(row), closing });
